@page "/dispatcher"
@rendermode InteractiveAuto
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>📦 Dispatcher Dashboard</h1>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search by tracking #, destination, or recipient..."
               @bind="searchTerm" @bind:event="oninput" @onkeyup="HandleSearch" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="selectedStatus">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-primary w-100" @onclick="LoadShipments">
            🔍 Filter
        </button>
    </div>
    <div class="col-md-3 text-end">
        <button class="btn btn-success" @onclick="ToggleCreateForm">
            ➕ New Shipment
        </button>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-header bg-success text-white">Create New Shipment</div>
        <div class="card-body">
            <div class="row g-3">
                <div class="col-md-4">
                    <label class="form-label">Tracking Number</label>
                    <input class="form-control" @bind="newShipment.TrackingNumber" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Origin</label>
                    <input class="form-control" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Destination</label>
                    <input class="form-control" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Sender</label>
                    <input class="form-control" @bind="newShipment.SenderName" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Recipient</label>
                    <input class="form-control" @bind="newShipment.RecipientName" />
                </div>
                <div class="col-md-2">
                    <label class="form-label">Weight (kg)</label>
                    <input type="number" step="0.1" class="form-control" @bind="newShipment.WeightKg" />
                </div>
                <div class="col-md-2">
                    <label class="form-label">Est. Delivery</label>
                    <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-md-2">
                    <label class="form-label">Notes</label>
                    <input class="form-control" @bind="newShipment.Notes" />
                </div>
                <div class="col-12">
                    <button class="btn btn-success me-2" @onclick="CreateShipment">Create</button>
                    <button class="btn btn-secondary" @onclick="ToggleCreateForm">Cancel</button>
                </div>
            </div>
            @if (!string.IsNullOrEmpty(createError))
            {
                <div class="alert alert-danger mt-2">@createError</div>
            }
        </div>
    </div>
}

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments.Count == 0)
{
    <div class="alert alert-info">No shipments found.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Weight</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in shipments)
                {
                    <tr>
                        <td><strong>@s.TrackingNumber</strong></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td>@s.WeightKg kg</td>
                        <td>
                            <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
                        </td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                            {
                                <select class="form-select form-select-sm d-inline-block w-auto"
                                        @onchange="e => UpdateStatus(s, e)">
                                    <option value="" selected disabled>Change…</option>
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        @if (status != s.Status)
                                        {
                                            <option value="@((int)status)">@status</option>
                                        }
                                    }
                                </select>
                            }
                            else
                            {
                                <span class="text-muted">—</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [Inject] private ShipmentService ShipmentSvc { get; set; } = default!;

    private List<ShipmentDto> shipments = [];
    private bool loading = true;
    private string searchTerm = "";
    private string selectedStatus = "";
    private bool showCreateForm;
    private ShipmentDto newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(7), ShippedDate = DateTime.UtcNow };
    private string? createError;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        ShipmentStatus? status = Enum.TryParse<ShipmentStatus>(selectedStatus, out var parsed) ? parsed : null;
        shipments = await ShipmentSvc.GetShipmentsAsync(status, string.IsNullOrWhiteSpace(searchTerm) ? null : searchTerm);
        loading = false;
    }

    private async Task HandleSearch()
    {
        await LoadShipments();
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out var statusInt))
        {
            var newStatus = (ShipmentStatus)statusInt;
            var updated = await ShipmentSvc.UpdateStatusAsync(shipment.Id, newStatus);
            if (updated != null)
            {
                var index = shipments.FindIndex(s => s.Id == shipment.Id);
                if (index >= 0)
                    shipments[index] = updated;
            }
        }
    }

    private void ToggleCreateForm()
    {
        showCreateForm = !showCreateForm;
        createError = null;
        if (showCreateForm)
            newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(7), ShippedDate = DateTime.UtcNow };
    }

    private async Task CreateShipment()
    {
        createError = null;
        if (string.IsNullOrWhiteSpace(newShipment.TrackingNumber) ||
            string.IsNullOrWhiteSpace(newShipment.Destination))
        {
            createError = "Tracking number and destination are required.";
            return;
        }

        var created = await ShipmentSvc.CreateShipmentAsync(newShipment);
        if (created != null)
        {
            showCreateForm = false;
            await LoadShipments();
        }
        else
        {
            createError = "Failed to create shipment. The tracking number may already exist.";
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@page "/track/{TrackingNumber}"
@rendermode InteractiveAuto

<PageTitle>Track Shipment</PageTitle>

<h1>🔎 Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control form-control-lg"
                   placeholder="Enter tracking number (e.g. TRK-20260001)"
                   @bind="trackingInput" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary btn-lg" @onclick="TrackShipment">
                Track
            </button>
        </div>
    </div>
</div>

@if (searching)
{
    <p><em>Searching...</em></p>
}
else if (notFound)
{
    <div class="alert alert-warning">
        <strong>Not found.</strong> No shipment matches tracking number <code>@searchedNumber</code>.
        Please double-check and try again.
    </div>
}
else if (shipment != null)
{
    <div class="card">
        <div class="card-header bg-dark text-white d-flex justify-content-between align-items-center">
            <span><strong>@shipment.TrackingNumber</strong></span>
            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <h5>Shipment Details</h5>
                    <table class="table table-borderless">
                        <tr><th>From</th><td>@shipment.Origin</td></tr>
                        <tr><th>To</th><td>@shipment.Destination</td></tr>
                        <tr><th>Sender</th><td>@shipment.SenderName</td></tr>
                        <tr><th>Recipient</th><td>@shipment.RecipientName</td></tr>
                        <tr><th>Weight</th><td>@shipment.WeightKg kg</td></tr>
                    </table>
                </div>
                <div class="col-md-6">
                    <h5>Delivery Timeline</h5>
                    <table class="table table-borderless">
                        <tr><th>Shipped</th><td>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</td></tr>
                        <tr>
                            <th>Estimated Delivery</th>
                            <td>
                                <strong>@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</strong>
                                @if (shipment.Status != ShipmentStatus.Delivered && shipment.EstimatedDelivery > DateTime.UtcNow)
                                {
                                    var daysLeft = (shipment.EstimatedDelivery - DateTime.UtcNow).Days;
                                    <br /><span class="text-muted">(@daysLeft day@(daysLeft != 1 ? "s" : "") remaining)</span>
                                }
                            </td>
                        </tr>
                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <tr>
                                <th>Delivered On</th>
                                <td class="text-success fw-bold">
                                    @shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")
                                </td>
                            </tr>
                        }
                    </table>
                </div>
            </div>

