@page "/track"
@page "/track/{TrackingNumber}"
@rendermode InteractiveAuto

<PageTitle>Track Shipment</PageTitle>

<h1>🔎 Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control form-control-lg"
                   placeholder="Enter tracking number (e.g. TRK-20260001)"
                   @bind="trackingInput" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary btn-lg" @onclick="TrackShipment">
                Track
            </button>
        </div>
    </div>
</div>

@if (searching)
{
    <p><em>Searching...</em></p>
}
else if (notFound)
{
    <div class="alert alert-warning">
        <strong>Not found.</strong> No shipment matches tracking number <code>@searchedNumber</code>.
        Please double-check and try again.
    </div>
}
else if (shipment != null)
{
    <div class="card">
        <div class="card-header bg-dark text-white d-flex justify-content-between align-items-center">
            <span><strong>@shipment.TrackingNumber</strong></span>
            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <h5>Shipment Details</h5>
                    <table class="table table-borderless">
                        <tr><th>From</th><td>@shipment.Origin</td></tr>
                        <tr><th>To</th><td>@shipment.Destination</td></tr>
                        <tr><th>Sender</th><td>@shipment.SenderName</td></tr>
                        <tr><th>Recipient</th><td>@shipment.RecipientName</td></tr>
                        <tr><th>Weight</th><td>@shipment.WeightKg kg</td></tr>
                    </table>
                </div>
                <div class="col-md-6">
                    <h5>Delivery Timeline</h5>
                    <table class="table table-borderless">
                        <tr><th>Shipped</th><td>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</td></tr>
                        <tr>
                            <th>Estimated Delivery</th>
                            <td>
                                <strong>@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</strong>
                                @if (shipment.Status != ShipmentStatus.Delivered && shipment.EstimatedDelivery > DateTime.UtcNow)
                                {
                                    var daysLeft = (shipment.EstimatedDelivery - DateTime.UtcNow).Days;
                                    <br /><span class="text-muted">(@daysLeft day@(daysLeft != 1 ? "s" : "") remaining)</span>
                                }
                            </td>
                        </tr>
                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <tr>
                                <th>Delivered On</th>
                                <td class="text-success fw-bold">
                                    @shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")
                                </td>
                            </tr>
                        }
                    </table>
                </div>
            </div>

            @if (!string.IsNullOrWhiteSpace(shipment.Notes))
            {
                <div class="alert alert-info mt-3">
                    <strong>Notes:</strong> @shipment.Notes
                </div>
            }

            <!-- Status progress bar -->
            <div class="mt-4">
                <h5>Status Progress</h5>
                <div class="d-flex justify-content-between position-relative mt-3 mb-2">
                    @{
                        var steps = new[] {
                            ShipmentStatus.Pending,
                            ShipmentStatus.PickedUp,
                            ShipmentStatus.InTransit,
                            ShipmentStatus.OutForDelivery,
                            ShipmentStatus.Delivered
                        };
                    }
                    @foreach (var step in steps)
                    {
                        var isActive = shipment.Status >= step && shipment.Status != ShipmentStatus.Cancelled;
                        <div class="text-center flex-fill">
                            <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(isActive ? "bg-success" : "bg-secondary")"
                                 style="width:36px;height:36px;color:white;font-weight:bold;">
                                @(isActive ? "✓" : "○")
                            </div>
                            <div class="small mt-1">@step</div>
                        </div>
                    }
                </div>
                @if (shipment.Status == ShipmentStatus.Cancelled)
                {
                    <div class="alert alert-danger mt-2">This shipment has been <strong>cancelled</strong>.</div>
                }
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public string? TrackingNumber { get; set; }
    [Inject] private ShipmentService ShipmentSvc { get; set; } = default!;

    private string trackingInput = "";
    private bool searching;
    private bool notFound;
    private string? searchedNumber;
    private ShipmentDto? shipment;

    protected override async Task OnInitializedAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            trackingInput = TrackingNumber;
            await TrackShipment();
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingInput))
            return;

        searching = true;
        notFound = false;
        shipment = null;
        searchedNumber = trackingInput.Trim();

        shipment = await ShipmentSvc.TrackShipmentAsync(searchedNumber);
        notFound = shipment == null;
        searching = false;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

